def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 2, 3, 6):
                points[grid[r][c]] = (r, c)

    horizontal = set()
    vertical = set()

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    if 1 in points:
        r, c = points[1]
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    if 2 in points:
        r, c = points[2]
        put(r, c - 4, 2)
        for x in range(c - 3, c):
            put(r, x, 5)
            horizontal.add((r, x))

    if 3 in points:
        r, c = points[3]
        put(r + 3, c, 3)
        for y in range(r + 1, r + 3):
            put(y, c, 5)
            vertical.add((y, c))

    if 6 in points:
        r, c = points[6]
        put(r - 6, c, 6)
        for y in range(r - 1, r - 6, -1):
            put(y, c, 5)
            vertical.add((y, c))

    crossings = horizontal & vertical
    for r, c in crossings:
        put(r, c, 4)
        y, x = r + 1, c - 1
        while y < h and x >= 0:
            put(y, x, 4)
            y += 1
            x -= 1

    return out
